import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BsgK4TUM.js";const h=JSON.parse('{"title":"Discounts","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/discounts.md","filePath":"user-guide/discounts.md"}'),i={name:"user-guide/discounts.md"};function n(c,e,d,r,u,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="discounts" tabindex="-1">Discounts <a class="header-anchor" href="#discounts" aria-label="Permalink to &quot;Discounts&quot;">​</a></h1><p>Discounts in Community Store can either be automatically applied to shopping carts/orders, or applied using discount codes.</p><h2 id="discount-rules" tabindex="-1">Discount Rules <a class="header-anchor" href="#discount-rules" aria-label="Permalink to &quot;Discount Rules&quot;">​</a></h2><p>A discount rule defines the type and amount of discount applied to an order, and importantly under what circumstances it applies. A discount rule can be configured to:</p><ul><li>either deduct a percentage, deduct a value once, deduct a value from each matching item, or change the price to a set value</li><li>deduct the discount from the items sub-total or the shipping</li><li>apply automatically, or through the use of discount codes</li><li>apply within a certain date range</li><li>apply to selected groups of products</li><li>be available to selected user groups only</li><li>apply when the item count in a cart is within a minimum and maximum</li></ul><p>Using the above restrictions, discounts can be configured to target very specific use-cases. Multiple discount rules can be created and made active at once.</p><h3 id="code-based-discounts" tabindex="-1">Code based Discounts <a class="header-anchor" href="#code-based-discounts" aria-label="Permalink to &quot;Code based Discounts&quot;">​</a></h3><p>To enter codes for a code based discount, first configure and create the discount rule. Once saved, a <strong>Manage Codes</strong> button is made available. Within the codes page, enter each code to be used to trigger the discount on a new line within the Code(s) field.</p><div class="tip custom-block"><p class="custom-block-title">Codes are case-insensitive</p><p>Note that entered codes are case-insensitive, meaning that a code entered as <code>DISCOUNT123</code> is the same as <code>discount123</code>, and a customer can enter either variant to apply that discount.</p></div><p>When code based discounts are selected on a discount rule there is the option to make them &#39;Single Use Code&#39;. When selected, codes entered into the code list can only be used once and are immediately removed. This is applicable for cases where you might want to offer a customer a one-off discount, or are printing discount vouchers.</p>',10)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
